-- 0057: الأدلة العامة لإدارة الخدمات الفنية (scope=general) في manual_templates: دليل المقاول، معايير التصميم، استخدام المنصة، مدير المنشأة، لجنة الاستلام
-- لكل دليل عام اعتماد وإصدار وسجل في القالب نفسه. وقاعدتان: R-43 (دليل المقاول جزء من العقد) وR-44 (كل تصميم على دليل المعايير). البذرة لا تستبدل التعديلات.
alter table public.manual_templates add column if not exists scope text not null default 'facility';
alter table public.manual_templates add column if not exists sort int not null default 0;
alter table public.manual_templates add column if not exists icon text not null default '';
alter table public.manual_templates add column if not exists status text not null default 'draft';
alter table public.manual_templates add column if not exists ver int not null default 0;
alter table public.manual_templates add column if not exists issued_at timestamptz;
alter table public.manual_templates add column if not exists issued_by text;
alter table public.manual_templates add column if not exists log jsonb not null default '[]'::jsonb;

insert into public.manual_templates(code,title,audience,sections,scope,sort,icon) values ('contractor','دليل المقاول للعمل داخل المنشآت المشغّلة','مقاولو المشاريع والتشغيل والصيانة والموردون وعمالتهم، ومهندسو المشاريع المشرفون عليهم','[{"key": "about", "title": "عن هذا الدليل", "body": "منشآت التجمع تعمل ومرضاها فيها أثناء تنفيذ الأعمال. هذا الدليل يحدد ما يلتزم به كل مقاول يعمل داخل منشأة مشغّلة أو بجوارها، حتى لا يكون العمل خطراً على مريض أو موظف أو على الخدمة.\n- يُرفق الدليل بكراسة الطرح، ويُعد جزءاً من التزامات العقد (R-43).\n- يوقّع المقاول إقرار الالتزام في آخر الدليل قبل المباشرة، ويُحفظ في مستندات المشروع.\n- مهندس المشروع هو جهة التواصل الوحيدة للمقاول مع المنشأة وأقسام الإدارة، ما لم يُحدَّد غير ذلك كتابياً.\n> المرجعية: معايير سباهي للمنشآت الصحية (فصل إدارة المرافق والسلامة)، ونظام تقييم مخاطر العدوى أثناء الإنشاء (ICRA)، وكود الحماية من الحريق السعودي، وإجراءات الإدارة المذكورة في كل قسم."}, {"key": "before", "title": "قبل المباشرة", "body": "لا يدخل المقاول الموقع للعمل حتى تكتمل هذه المتطلبات ويؤكدها مهندس المشروع:\n| المتطلب | من يقدّمه | من يعتمده | المرجع |\n| قائمة العمالة بأسمائهم ومهنهم وإقاماتهم وشهاداتهم | المقاول | مهندس المشروع | R-21 |\n| تهيئة السلامة لكل عامل وبطاقة دخول | الأمن والسلامة | الأمن والسلامة | H-07 |\n| خطة التنسيق التشغيلي (المناطق، المسارات، الأوقات، البدائل) | المقاول ومهندس المشروع | المنشأة والمرافق | G-10، R-06 |\n| تقييم مخاطر العدوى ICRA وفئة الحماية | مهندس المشروع | مكافحة العدوى | R-06 |\n| خطة السلامة للمشروع وتقييم المخاطر | المقاول | الأمن والسلامة | H-07 |\n| البرنامج الزمني وخط الأساس | المقاول | قسم المشاريع | P-04 |\n| تأمين المسؤولية والعمالة حسب العقد | المقاول | قسم المشاريع | العقد |\n## اجتماع المباشرة\n- يحضره المقاول ومهندس المشروع وممثلو المنشأة والمرافق والأمن والسلامة ومكافحة العدوى.\n- يُشرح فيه هذا الدليل، وتُسلَّم نقاط التواصل وأرقام الطوارئ، ويُعتمد محضره في المنصة (P-12).", "auto": "procs", "procs": "P-04 · G-10 · H-07"}, {"key": "access", "title": "الدخول والحركة داخل المنشأة", "body": "- البطاقة ظاهرة طوال الوجود في المنشأة، ولا دخول لعامل بلا بطاقة (R-21).\n- الدخول والخروج من المدخل المحدد للمقاولين فقط، لا من مداخل المرضى.\n- الحركة داخل المنشأة في المسارات المعتمدة في خطة التنسيق، ولا دخول لمناطق المرضى إلا لموقع العمل.\n- المصاعد: مصعد الخدمة المحدد فقط، ومصاعد المرضى ممنوعة على العمالة والمواد.\n- المواقف ومناطق التخزين ومواقع المكاتب المؤقتة يحددها مهندس المشروع مع المرافق.\n- ساعات العمل المعتمدة في خطة التنسيق، والعمل خارجها في المناطق المشغّلة بموافقة مسبقة.\n- يُمنع التدخين والأكل في مواقع العمل وداخل المنشأة، وتُمنع الصور لغير أغراض العمل.", "auto": "procs", "procs": "H-05"}, {"key": "permits", "title": "تصاريح العمل والعزل الآمن", "body": "الأعمال التالية لا تبدأ إلا بتصريح عمل مكتوب صالح للوردية، معلق في الموقع (M-01، R-13):\n| نوع العمل | أمثلة | ضوابط أساسية |\n| الأعمال الساخنة | لحام، قطع، تجليخ، لهب مكشوف | إزالة المواد القابلة للاشتعال، طفاية، مراقب حريق أثناء العمل و30 دقيقة بعده |\n| العزل الكهربائي والميكانيكي | العمل على لوحات أو معدات أو أنابيب تحت ضغط | قفل وبطاقة لكل عامل، والتحقق من انعدام الطاقة |\n| الأماكن المحصورة | خزانات، غرف تفتيش، مجارٍ | قياس الغازات، تهوية، مراقب خارجي، خطة إنقاذ |\n| العمل على ارتفاع | أكثر من 1.8 م، الأسطح | سقالات أو منصات معتمدة، أحزمة مربوطة |\n| فتح الأسقف في مناطق المرضى | تمديدات فوق السقف | تصنيف ICRA وحواجز |\n| أي عمل يعطّل نظام سلامة | الإنذار، الرشاشات، الأبواب | سجل تعطيل وإجراءات بديلة (H-01) |\n! أي تغيير في نطاق العمل أو ظروفه يوقف العمل ويستلزم تصريحاً جديداً. التصريح يُغلق بتوقيع المقاول ومُصدر التصريح بعد إزالة العزل وتنظيف الموقع.", "auto": "procs", "procs": "M-01 · H-01"}, {"key": "icra", "title": "مكافحة العدوى أثناء الأعمال", "body": "فئة الحماية تحددها مكافحة العدوى بحسب نوع العمل وخطورة المنطقة، ويلتزم المقاول بضوابطها كاملة طوال العمل:\n| الفئة | متى | الضوابط |\n| الأولى | أعمال تفتيش وصيانة بسيطة لا تولد غباراً | تقليل الغبار، إعادة أي بلاطة سقف فوراً |\n| الثانية | أعمال صغيرة تولد غباراً محدوداً | رش الأسطح، سد الفتحات، ممسحة لاصقة، تغطية النقل |\n| الثالثة | أعمال تولد غباراً متوسطاً أو هدماً محدوداً | حواجز صلبة محكمة قبل البدء، ضغط سالب بمرشح HEPA، ممر نظيف |\n| الرابعة | أعمال كبيرة أو في مناطق عالية الخطورة | حواجز كاملة مع غرفة انتقال، ضغط سالب مراقب، ملابس واقية تُخلع عند الخروج |\n- لا تبدأ أعمال الفئتين الثالثة والرابعة إلا بعد تفتيش مكافحة العدوى للحواجز.\n- المخلفات تُنقل في حاويات مغطاة، عبر المسار والأوقات المحددة، ولا تمر في مناطق المرضى.\n- عند الانتهاء: تنظيف كامل قبل إزالة الحواجز، وتفتيش قبل إعادة المنطقة للتشغيل (F-01).", "auto": "procs", "procs": "G-10 · F-01"}, {"key": "safety", "title": "السلامة المهنية", "body": "- معدات الوقاية الشخصية إلزامية بحسب العمل: خوذة، حذاء سلامة، نظارات، قفازات، سترة عاكسة، وحماية سمع وتنفس عند الحاجة.\n- السقالات والسلالم والمنصات بشهادة فحص سارية، ولا تُترك في الممرات.\n- التوصيلات الكهربائية المؤقتة من لوحة مؤقتة محمية بقاطع تسرب أرضي، ولا كوابل في الممرات أو المياه.\n- النظافة اليومية للموقع، ولا تُترك مواد أو أدوات في مناطق يصلها المرضى.\n- الأدوات والمعدات تُخزن مقفلة نهاية كل يوم.\n! للأمن والسلامة حق إيقاف أي عمل فوراً عند خطر وشيك، دون انتظار اعتماد (R-24). استئناف العمل بعد زوال الخطر وموافقتهم.", "auto": "procs", "procs": "H-07"}, {"key": "fire", "title": "السلامة من الحريق أثناء الأعمال", "body": "- لا يُعطَّل أي كاشف أو رشاش أو باب حريق إلا بسجل تعطيل وإجراءات سلامة بديلة تنفذها المنشأة (H-01، R-14).\n- مخارج الطوارئ وممراتها خالية دائماً، ولا تُغلق ولا يُخزن فيها.\n- طفاية مناسبة في كل موقع عمل، وطفايتان على الأقل مع الأعمال الساخنة.\n- المواد القابلة للاشتعال تُخزن خارج المبنى أو في مخزن معتمد بأقل كمية لازمة.\n- أي فتحات في الجدران والأسقف الفاصلة للحريق تُسد بمواد معتمدة لمقاومة الحريق قبل إغلاق السقف.", "auto": "procs", "procs": "H-01 · H-06"}, {"key": "shutdown", "title": "إيقاف المرافق والأنظمة", "body": "أي حاجة لإيقاف كهرباء أو مياه أو غازات طبية أو تكييف أو شبكة عن أي جزء من المنشأة:\n- طلب من المقاول عبر مهندس المشروع قبل 48 ساعة على الأقل، بالمنطقة والمدة والسبب.\n- لا يُنفذ إلا بعد اعتماد الإيقاف وإشعار المنشأة وتجهيز البديل (M-02، R-15).\n- التنفيذ بحضور فني الصيانة، والإعادة واختبار التشغيل قبل مغادرة الموقع.", "auto": "procs", "procs": "M-02"}, {"key": "waste", "title": "المواد الخطرة والمخلفات", "body": "- كل مادة كيميائية تدخل الموقع معها بطاقة بيانات السلامة، وتُخزن بحسب التوافق (R-20، H-04).\n- المخلفات الإنشائية تُرفع يومياً، ولا تُخلط بنفايات المنشأة الطبية أو العامة (S-02).\n- الانسكابات تُحتوى فوراً وتُبلَّغ للأمن والسلامة.", "auto": "procs", "procs": "H-04 · S-02"}, {"key": "nuisance", "title": "الضوضاء والاهتزاز والغبار", "body": "- الأعمال الصاخبة (التكسير، الحفر، القص) في الأوقات المتفق عليها في خطة التنسيق، وبعيداً عن أوقات ذروة العيادات والعمليات.\n- قبل أي عمل يولد اهتزازاً قرب غرف العمليات أو الأجهزة الحساسة يُنسق مع المنشأة لتحديد الوقت.\n- أي شكوى من المنشأة تُعالج فوراً، وقد تؤدي لإيقاف العمل مؤقتاً."}, {"key": "quality", "title": "الجودة والاعتمادات", "body": "- لا تُورَّد مادة ولا تُركب قبل اعتمادها: العينات، والمواد، ومخططات الورشة (P-06).\n- الخامات المعتمدة في هوية التجمع لها رموز ثابتة؛ لا بديل لها إلا باعتماد مكتوب.\n- طلبات الفحص قبل إغلاق أي عمل مخفي (تمديدات قبل السقف، عزل قبل التبليط).\n- الأعمال غير المطابقة تُزال وتُعاد على حساب المقاول.", "auto": "procs", "procs": "P-06"}, {"key": "reports", "title": "التقارير والاجتماعات والمراسلات", "body": "- تقرير يومي أو أسبوعي بالأعمال والعمالة والمعوقات، بحسب ما يطلبه مهندس المشروع.\n- اجتماع متابعة دوري بمحضر وقرارات في المنصة (P-05، P-12).\n- كل مراسلة رسمية مكتوبة ومرقمة عبر قسم المشاريع (P-11)، ولا يُعتد بالتعليمات الشفهية في الأمور المالية والزمنية.\n- طلبات التغيير والتمديد تمر بإجراء أوامر التغيير وحدود الاعتماد (P-08، A-06..A-08).", "auto": "procs", "procs": "P-05 · P-08 · P-11 · P-12"}, {"key": "incident", "title": "الحوادث والطوارئ", "body": "- أي حادث أو إصابة أو شبه حادث يُبلَّغ فوراً لمهندس المشروع والأمن والسلامة، ويُكتب تقريره (R-19، H-03).\n- عند إنذار الحريق: إيقاف العمل والأدوات الساخنة، والخروج من أقرب مخرج إلى نقطة التجمع، واتباع تعليمات المنشأة.\n- عند تسبب العمل في تسرب أو انقطاع: الإبلاغ الفوري للصيانة، وعدم محاولة الإصلاح دون توجيه (G-11).", "auto": "procs", "procs": "H-03 · G-11"}, {"key": "handover", "title": "الاستلام والتسليم", "body": "المشروع لا يُستلم ابتدائياً إلا بملف تسليم كامل، ويُعد المقاول مدخلاته:\n| ما يسلّمه المقاول | الغرض | المرجع |\n| مخططات كما نُفذ (As-built) لكل التخصصات | التشغيل والتعديلات المستقبلية | G-04 |\n| كتيبات التشغيل والصيانة وشهادات الاختبار | الصيانة | G-04 |\n| بيانات الأنظمة ونقاط الإغلاق والعزل | دليل التشغيل والصيانة للمنشأة | R-42 |\n| رموز الخامات المستخدمة ومصادرها | الصيانة والاستبدال بالمثل | R-42 |\n| قطع الغيار والمفاتيح والأدوات | المخزون الاحتياطي | M-05 |\n| شهادات الضمان وخطاباته | المطالبة بالعيوب | P-14 |\n| تدريب فرق التشغيل | تشغيل آمن من اليوم الأول | G-04 |\n- تُغلق ملاحظات الاستلام في المهل المحددة بالمحضر (P-13).\n- خلال فترة الضمان يستجيب المقاول لبلاغات العيوب في المهلة التعاقدية (P-14).", "auto": "procs", "procs": "G-04 · P-13 · P-14"}, {"key": "violations", "title": "المخالفات والجزاءات", "body": "| المخالفة | الإجراء |\n| مخالفة بسيطة لأول مرة (نظافة، بطاقة) | تنبيه شفهي يُسجَّل |\n| تكرار المخالفة أو مخالفة متوسطة | إنذار كتابي عبر قسم المشاريع |\n| خطر وشيك أو عمل عالي الخطورة بلا تصريح | إيقاف العمل فوراً (R-24) |\n| تكرار بعد الإنذار أو ضرر بالمنشأة | تطبيق الحسميات والغرامات بنص العقد (A-11) |\n- تُحتسب المخالفات في تقييم أداء المقاول عند الاستلام (C-02)."}, {"key": "pledge", "title": "إقرار المقاول", "body": "نقر نحن المقاول الموقّع أدناه بأننا اطلعنا على هذا الدليل وفهمناه، ونلتزم به وبإجراءات المنشأة، ونتحمل مسؤولية التزام عمالتنا ومقاولينا من الباطن به.\n| المشروع | |\n| اسم المقاول | |\n| اسم المفوض بالتوقيع وصفته | |\n| التوقيع والختم | |\n| التاريخ | |"}]'::jsonb,'general',1,'crane') on conflict (code) do nothing;
insert into public.manual_templates(code,title,audience,sections,scope,sort,icon) values ('design','دليل معايير التصميم للمنشآت الصحية','المصممون والاستشاريون ومهندسو المشاريع ولجان مراجعة التصميم','[{"key": "about", "title": "عن هذا الدليل", "body": "يُرفق هذا الدليل مع كل تكليف تصميم أو تأهيل لمنشأة في التجمع، حتى تخرج كل منشأة على معيار واحد وهوية واحدة، ولا يبدأ كل مشروع من الصفر (R-44).\n- ما في هذا الدليل حد أدنى؛ ويُطبَّق معه كود البناء السعودي واشتراطات الدفاع المدني ومعايير سباهي والأدلة الإرشادية لوزارة الصحة، والأشد هو الملزم.\n- أي خروج عن الدليل يحتاج مبرراً مكتوباً يعتمده رئيس قسم المشاريع قبل اعتماد التصميم."}, {"key": "principles", "title": "مبادئ التصميم", "body": "| المبدأ | ماذا يعني في التصميم |\n| حول المريض | المسار من المدخل إلى الخدمة واضح وقصير، والانتظار مريح ومرئي من الاستقبال |\n| الخدمة عند نقطة الرعاية | ما يحتاجه الطبيب والممرض في الغرفة نفسها: المغسلة، الكاونتر، التخزين، الحاسب |\n| مكافحة العدوى | أسطح بلا فواصل، مغاسل في كل غرفة كشف، فصل النظيف عن المتسخ |\n| لا حاجز بين الطبيب والمريض | محطة الطبيب جانبية لا مكتب فاصل، والكرسيان على مستوى واحد |\n| التصميم للصيانة | قطع قياسية، فتحات وصول، أنظمة يمكن عزلها جزئياً، خامات تدوم |\n| هوية واحدة | اللوحة والشعار والألوان والخامات المعتمدة في كل منشأة |\n| الوصول الشامل | كل فراغ عام يصله الكرسي المتحرك دون عائق |"}, {"key": "process", "title": "مسار التصميم والمراجعات", "body": "التصميم يمر بالمراجعات التالية قبل الطرح، وكل مراجعة تُسجَّل في المنصة:\n| المرحلة | ما يُراجَع | من يراجع | المرجع |\n| دراسة الاحتياج | النطاق وتحويله لمشروع | المرافق والمشاريع | G-02، R-01 |\n| التصميم المبدئي | البرنامج الوظيفي والمسقط والمسارات | المنشأة ومكافحة العدوى والمشاريع | P-01 |\n| التصميم التفصيلي | الأنظمة والسلامة من الحريق والتقنية | الصيانة والأمن والسلامة وتقنية المعلومات | R-04 |\n| الأجهزة الطبية | مواقعها ومتطلباتها | الصيانة الطبية والتجهيزات الطبية | R-29، G-07 |\n| جدول الكميات والمواصفات | على المرجع الفني وبنود المقطوعية | المشاريع | P-02 |\n| الاعتماد للطرح | اكتمال المخرجات | رئيس قسم المشاريع ومدير الإدارة | A-03 |", "auto": "procs", "procs": "G-02 · P-01 · P-02 · P-03 · G-07"}, {"key": "spaces", "title": "الفراغات النموذجية", "body": "| الفراغ | العناصر الإلزامية |\n| عيادة الكشف | كاونتر جداري متصل، محطة طبيب جانبية، مغسلة غسل أيدي، سرير كشف خلف ستارة فصل مضادة للبكتيريا، تخزين مغلق |\n| غرفة الإجراءات | مغسلة جراحية أو غسل أيدي، إنارة فحص، مخارج غازات بحسب الخدمة، أسطح قابلة للتطهير |\n| التنويم | دورة مياه داخلية مهيأة، وحدة رأس السرير، مغسلة عند المدخل، إنارة ليلية، حماية جدران |\n| الانتظار | مقاعد معتمدة، رؤية للاستقبال، شاشة نداء، قرب دورات المياه، مساحة للكرسي المتحرك |\n| الاستقبال | كاونتر بمستويين أحدهما لذوي الإعاقة، رؤية للمدخل والانتظار |\n| المغسلة المتسخة والنظيفة | فصل تام بينهما، أرضية بلا فواصل، تصريف مناسب |\n| غرف الأنظمة | وصول من خارج مناطق المرضى، تهوية، مساحة صيانة حول المعدات |\n- المساقط المعتمدة للعيادة وغرف التنويم ومواصفاتها وجداول كمياتها جاهزة في المرجع الفني وبنود المقطوعية، ويُبدأ منها."}, {"key": "identity", "title": "الهوية الخارجية والإرشاد", "body": "- لوحة الواجهة الموحدة: الشعار والاسم بالعربية والإنجليزية، بالمقاس والإضاءة والمواد المعتمدة.\n- اللوحة في موقع مرئي من الشارع والمدخل، ومضاءة ليلاً.\n- الإرشاد الداخلي: لوحات الأقسام ولوحات الغرف بالرمز والاسم، بالخط والألوان المعتمدة.\n- لا لوحات أو ملصقات اجتهادية خارج نظام الإرشاد."}, {"key": "materials", "title": "الخامات والتشطيبات", "body": "| العنصر | المعتمد | غير المقبول | السبب |\n| الأرضيات في المناطق السريرية | فينيل ملحوم بلا فواصل مع حواف مقلوبة على الجدار | البلاط بفواصل | مكافحة العدوى وسهولة التنظيف |\n| الجدران في الممرات والغرف | دهان قابل للغسل مع حماية جدران وزوايا | ورق الجدران والأسطح المسامية | المتانة والتطهير |\n| الأسقف | بلاطات قابلة للفك في المناطق العامة، ومصمتة في المناطق المعقمة | أسقف لا يمكن الوصول خلفها في الممرات | الصيانة ومكافحة العدوى |\n| الإنارة | وحدات LED بمعامل لون مناسب للفحص | وحدات يصعب الحصول على قطعها | الصيانة والراحة البصرية |\n| النوافذ في المناطق السريرية | ثابتة أو بفتح محدود | نوافذ تفتح بالكامل | السلامة وضغط الهواء |\n| الكاونترات | أسطح مصمتة بلا فواصل | الخشب المكشوف | التطهير |\n- كل خامة في جدول الكميات برمزها في المرجع الفني، ويُسلَّم رمزها في دليل المنشأة (R-42)."}, {"key": "coding", "title": "ترميز الغرف", "body": "كل فراغ يأخذ رمزاً ثابتاً قبل الطرح، يُكتب على المخططات ولوحة الغرفة ويُسجَّل في المنصة (R-16، F-03):\n| الجزء | المعنى | مثال |\n| الأول | القسم أو المنطقة | ER |\n| الثاني | الطابق | GF |\n| الثالث | رقم الغرفة | 001 |\n- مثال كامل: ER-GF-001.\n- لا يتغير الرمز بتغيير الاستخدام إلا بإجراء إدارة التغيير (G-12).", "auto": "procs", "procs": "F-03 · G-12"}, {"key": "systems", "title": "الأنظمة", "body": "- الكهرباء: تغذية احتياطية من المولد للأحمال الأساسية والمناطق الحرجة، وتمييز مقابس الطوارئ، ولوحات بجداول دوائر محدثة.\n- الغازات الطبية: مخارج بحسب الخدمة، وصمامات منطقة وإنذارات في مواقع يراها التمريض.\n- التكييف: ضغط موجب أو سالب للمناطق الخاصة (العزل، العمليات، التعقيم) بحسب الاشتراطات، وفلاتر مناسبة.\n- السلامة من الحريق: إنذار ورشاشات وفواصل حريق ومخارج بحسب كود الحماية من الحريق السعودي والدفاع المدني.\n- الشبكات والتيار الخفيف: يراجعها قسم تقنية المعلومات قبل الطرح (R-04).\n- كل نظام يُصمم بحيث يمكن عزل جزء منه دون إيقاف المبنى كله."}, {"key": "maint", "title": "التصميم للصيانة والتشغيل", "body": "- فتحات وصول لكل صمام ومخمد ووحدة فوق الأسقف.\n- مساحة خدمة حول المعدات بحسب توصيات الصانع.\n- معدات وقطع قياسية متوفرة محلياً، وتوحيد الطرازات قدر الإمكان.\n- عدادات فرعية للكهرباء والمياه حيث يفيد القياس.\n- ترقيم وتمييز الأنابيب واللوحات والصمامات بالمواصفة.\n- مدخلات دليل التشغيل والصيانة (الأنظمة، نقاط الإغلاق، الخامات) تُطلب ضمن مخرجات المقاول (R-42)."}, {"key": "access", "title": "الوصول الشامل", "body": "- منحدرات بميول مريحة ودرابزين عند كل فرق منسوب في المسارات العامة.\n- أبواب بعرض يسمح بمرور الكرسي المتحرك والسرير حيث يلزم.\n- دورة مياه مهيأة لذوي الإعاقة في كل منطقة انتظار.\n- مواقف مخصصة قريبة من المدخل.\n- الأبعاد والتفاصيل بحسب كود البناء السعودي ومتطلبات الوصول الشامل المعتمدة."}, {"key": "deliverables", "title": "مخرجات التصميم المطلوبة", "body": "| المخرج | ملاحظات |\n| المخططات المعمارية والإنشائية والأنظمة | بالرموز المعتمدة للغرف |\n| جدول الكميات | على المرجع الفني أو بنود المقطوعية، بلا مبالغ ثابتة يحددها التجمع |\n| المواصفات الفنية | مرتبطة ببنود الجدول |\n| قوائم الأثاث والتجهيزات لكل فراغ | الأثاث المعتمد |\n| مخططات الإخلاء والسلامة | بحسب اشتراطات الدفاع المدني |\n| تقييم ICRA المبدئي للمراحل | للأعمال داخل منشأة مشغّلة |\n| خطة المراحل | إذا كانت المنشأة ستعمل أثناء التنفيذ |"}, {"key": "checklist", "title": "قائمة مراجعة التصميم", "body": "| البند | تحقق |\n| المسار من المدخل إلى الخدمة واضح وقصير | |\n| كل غرفة كشف فيها مغسلة غسل أيدي | |\n| الفصل بين النظيف والمتسخ | |\n| الخامات من المعتمد برموزها | |\n| رموز الغرف على المخططات | |\n| الأحمال الحرجة على التغذية الاحتياطية | |\n| مراجعة السلامة من الحريق والدفاع المدني | |\n| مراجعة تقنية المعلومات والصيانة الطبية | |\n| الوصول الشامل | |\n| اللوحة الموحدة والإرشاد | |"}]'::jsonb,'general',2,'ruler') on conflict (code) do nothing;
insert into public.manual_templates(code,title,audience,sections,scope,sort,icon) values ('platform','دليل استخدام منصة إدارة الخدمات الفنية','كل مستخدمي المنصة: موظفو المنشآت، الفنيون، موظفو الأقسام ورؤساؤها، مهندسو المشاريع، والقيادة','[{"key": "about", "title": "عن المنصة", "body": "منصة إدارة الخدمات الفنية (ahc-tsd.com) هي المكان الواحد لكل أعمال الإدارة: البلاغات والطلبات، أعمال الأقسام، المشاريع، الحوكمة والأدلة، وسيارات المقر. ما لا يُسجَّل في المنصة لا يُحتسب ولا يُتابع.\n- تعمل من المتصفح على الحاسب والجوال، ويمكن إضافتها للشاشة الرئيسية في الجوال كتطبيق.\n- كل مستخدم يرى ما يخصه بحسب دوره وقسمه ومنشأته."}, {"key": "login", "title": "الدخول والحساب", "body": "- الدخول بالبريد الإلكتروني المسجل في سجل المستخدمين المعتمد.\n- بعد الدخول الأول يعطيك مسؤول النظام دورك وقسمك أو منشأتك؛ حتى ذلك الحين يظهر حسابك «بانتظار التفعيل».\n- من «الإعدادات والإشعارات» تختار ما يصلك من إشعارات، وتفعل إشعارات الجوال."}, {"key": "basics", "title": "أساسيات الواجهة", "body": "| العنصر | ماذا يفعل |\n| القائمة الجانبية | الصفحات بحسب دورك، والأقسام تتفتح على صفحاتها |\n| يومي | ما ينتظرك اليوم: أعمال، مهام، إشارات، مواعيد |\n| البحث (⌘K أو Ctrl+K) | الوصول السريع لأي مشروع أو عمل برقمه |\n| الإشعارات | الجرس في الأعلى، وكل إشعار يفتح موضوعه |\n| الإشارة @ | في أي تعليق، تذكر زميلاً فيصله إشعار |"}, {"key": "requester", "title": "موظف المنشأة: كيف أرفع بلاغاً أو طلباً", "body": "- من «مركز البلاغات» اختر نوع الطلب (عطل، طلب خدمة، تقني، جهاز طبي…).\n- اختر الموقع برمز الغرفة، واكتب الوصف، وأرفق صورة (R-16).\n- يصلك رقم البلاغ، وتتابع حالته في «بلاغاتي»: جديد ← مقبول ← قيد التنفيذ ← تحقق ← مغلق.\n- عند الإغلاق قيّم الخدمة؛ التقييم يدخل في أداء القسم والمقاول.\n! الطوارئ (تسرب، انقطاع، دخان) اتصال مباشر بالصيانة أولاً، ثم البلاغ (R-09).", "auto": "procs", "procs": "G-01 · G-05"}, {"key": "tech", "title": "الفني: كيف أنفذ أعمالي", "body": "- «أعمالي» فيها ما أُسند إليك مرتباً بالأولوية والمهلة.\n- اقبل العمل، ثم «بدء التنفيذ» عند الوصول للموقع.\n- أغلق العمل بقائمة التحقق والنتيجة وصور قبل وبعد؛ لا يُغلق عمل بلا توثيق.\n- العمل الذي يحتاج تصريحاً أو إيقافاً يظهر لك متطلبه قبل البدء (M-01، M-02).", "auto": "procs", "procs": "G-05 · G-06"}, {"key": "dept", "title": "موظف القسم ورئيسه: إدارة أعمال القسم", "body": "| الصفحة | الاستخدام |\n| طلبات وأعمال القسم | الاستقبال والتوزيع والمتابعة بالسحب بين الحالات |\n| الأعمال المخططة | خطط الصيانة الدورية التي تولد أوامرها تلقائياً (G-06) |\n| سجل الأصول | الأصول بمواقعها وضماناتها وتاريخ أعطالها |\n| دليل القسم | إجراءات القسم وقواعده من الحوكمة |\n| الفريق | أعضاء القسم وأدوارهم |\n- رئيس القسم يرى مؤشرات قسمه: المتأخر، نسبة الإنجاز في المهلة، والتقييمات.", "auto": "procs", "procs": "G-06 · M-04"}, {"key": "engineer", "title": "مهندس المشاريع: إدارة المشروع", "body": "| تبويب المشروع | الاستخدام | الإجراء |\n| النظرة العامة والتحديثات | الحالة والتقدم والزيارات والمعوقات | P-05 |\n| الجدول الزمني | خط الأساس والتقدم المخطط والفعلي | P-04 |\n| جدول الكميات | من المرجع الفني وبنود المقطوعية، وتصدير Excel | P-02 |\n| الاعتمادات | العينات والمواد ومخططات الورشة | P-06 |\n| المستخلصات | الكميات المنفذة والصرف | P-07 |\n| أوامر التغيير | الزيادة والتمديد بحدود الاعتماد | P-08 |\n| المستندات والمخططات | المراسلات والإصدارات | P-11 |\n| الإغلاق | قائمة الإغلاق والاستلام والضمان وأدلة المنشأة | P-13، R-42 |", "auto": "procs", "procs": "P-01 · P-05 · P-08 · P-13"}, {"key": "leaders", "title": "القيادة ومدير الإدارة", "body": "- لوحة الإدارة: صورة حية لكل الأقسام والأعمال المتأخرة والمشاريع.\n- التقارير: التقرير الشهري للإدارة وتقارير المشاريع (P-15).\n- العروض التنفيذية: عرض جاهز للاجتماعات من بيانات المنصة.\n- الاعتمادات: الإجراءات والأدلة وأوامر التغيير ضمن حدود الاعتماد.", "auto": "procs", "procs": "P-15"}, {"key": "fleet", "title": "سيارات المقر", "body": "- من «سيارات المقر» يطلب الموظف سيارة بالغرض والوجهة ووقت الخروج والعودة.\n- يسلّم قسم الحركة السيارة بمحضر (العداد والوقود والحالة)، ويستلمها بمحضر في اليوم نفسه (V-01).\n- المبيت أو المهمة خارج المحافظة بطلب مسبق واعتماد (V-06).", "auto": "procs", "procs": "V-01 · V-06"}, {"key": "gov", "title": "الحوكمة والأدلة في المنصة", "body": "- «الحوكمة والأدلة»: الهيكل، موجّه الطلبات، مصفوفة الصلاحيات، الإطار الإداري، الإجراءات، القواعد.\n- كل إجراء فيه «يُنفَّذ في المنصة»: النموذج أو الشاشة التي تنفذه، والأعمال الجارية على خطواته.\n- «أدلة المنشآت»: دليل التشغيل والصيانة ودليل المستخدمين لكل منشأة، والأدلة العامة مثل هذا الدليل."}, {"key": "faq", "title": "أسئلة شائعة", "body": "## لا أجد صفحة يذكرها زميلي\nالصفحات تظهر بحسب الدور والقسم؛ إذا احتجت صلاحية اطلبها من رئيس قسمك.\n## رفعت بلاغاً على قسم خاطئ\nيحوّله الاستقبال الموحد في المرافق للقسم الصحيح، فلا داعي لرفعه مرة ثانية (R-05).\n## كيف أعرف من يعتمد طلبي\nمن «الإطار الإداري ← حدود الاعتماد» في الحوكمة."}]'::jsonb,'general',3,'monitor') on conflict (code) do nothing;
insert into public.manual_templates(code,title,audience,sections,scope,sort,icon) values ('fmanager','دليل مدير المنشأة','مديرو المستشفيات والمراكز الصحية ومن ينوب عنهم','[{"key": "about", "title": "دورك مع إدارة الخدمات الفنية", "body": "مدير المنشأة شريك أساسي للإدارة في سلامة المنشأة وجاهزيتها: يعرف احتياجها، ويتحمل مسؤولية سلوك كادرها فيها، ويعتمد ما يمس تشغيلها. هذا الدليل يجمع ما يخصك من إجراءات الإدارة في مكان واحد."}, {"key": "channels", "title": "قناة واحدة ومن تكلّم", "body": "كل احتياجات منشأتك تمر بقناة واحدة: مركز البلاغات في المنصة، ويصنّفها الاستقبال الموحد في المرافق خلال يوم عمل (R-05).\n| الحاجة | الجهة | المرجع |\n| عطل أو طلب صيانة | الصيانة عبر مركز البلاغات | G-05 |\n| حادث، حريق، تعطيل نظام حريق | الأمن والسلامة | H-03، H-01 |\n| إغلاق غرفة أو نقل أو تعديل مساحة | المرافق | F-01، G-12 |\n| مشروع تأهيل أو احتياج كبير | المرافق ثم المشاريع | G-02 |\n| جهاز طبي جديد أو عطل جهاز | التجهيزات الطبية / الصيانة الطبية | G-07، G-08 |\n| النظافة والنفايات والحشرات | الخدمات العامة | S-01، S-02 |\n| الشبكة والأنظمة | تقنية المعلومات | T-01 |", "auto": "procs", "procs": "G-01"}, {"key": "duties", "title": "مسؤولياتك الدورية", "body": "| التكرار | المسؤولية |\n| يومياً | متابعة البلاغات العاجلة في منشأتك وإبلاغ الإدارة بما يمس المرضى |\n| أسبوعياً | مراجعة البلاغات المفتوحة والمتأخرة وتقييم المغلق منها |\n| شهرياً | المشاركة في جولة بيئة الرعاية ومتابعة إغلاق ملاحظاتها (F-02) |\n| ربع سنوياً | التأكد من تنفيذ تمرين الإخلاء لكل وردية (K-11) |\n| نصف سنوياً | المشاركة في تمرين الطوارئ (K-12) |\n| سنوياً | المشاركة في تحليل قابلية التأثر بالمخاطر لمنشأتك (K-13)، ومراجعة دليل المنشأة (K-30) |", "auto": "procs", "procs": "F-02 · H-02"}, {"key": "closures", "title": "الإغلاق والإيقاف في منشأتك", "body": "- لا تُغلق غرفة أو عيادة إلا بإجراء الإغلاق وبديل تشغيلي معلن، ومستوى الاعتماد بحسب مدة الإغلاق وحساسية المنطقة (F-01، R-12).\n- الإيقاف المخطط للكهرباء أو المياه أو الغازات يصلك بإشعار مسبق، ودورك تجهيز البديل وإبلاغ الأقسام (M-02، R-15).\n- لا فتح بلا محضر: الغرفة المعادة تُستلم بعد التنظيف والفحص (R-11).", "auto": "procs", "procs": "F-01 · M-02"}, {"key": "projects", "title": "المشاريع في منشأتك", "body": "- قبل أي أعمال داخل منشأتك: خطة تنسيق تشمل المناطق والمسارات والأوقات والبدائل وتقييم مكافحة العدوى، وتُعرض عليك قبل المباشرة (G-10، R-06).\n- المقاول لا يدخل إلا بتهيئة وبطاقة وتصريح عند الحاجة، وأي مخالفة تبلّغ بها مهندس المشروع (R-21، دليل المقاول).\n- عند التسليم: يُسلَّم لك دليل مستخدمي المنشأة، ويُدرَّب كادرك على ما يلزم (R-42).\n- كل عيب في فترة الضمان يُبلَّغ مبكراً عبر المنصة (P-14).", "auto": "procs", "procs": "G-10 · G-04"}, {"key": "safety", "title": "السلامة والطوارئ", "body": "- خطة الطوارئ والإخلاء في منشأتك معلقة ومعروفة لكادرك، وأدوار الإخلاء مسندة لكل وردية (H-02).\n- عند تعطيل أي نظام حريق: تنفذ منشأتك الإجراءات البديلة المطلوبة (دوريات، منع الأعمال الساخنة، توعية الكادر) حتى إعادة النظام (H-01).\n- كل حادث أو شبه حادث يُبلَّغ (R-19).", "auto": "procs", "procs": "H-01 · H-02 · H-03"}, {"key": "security", "title": "الأمن ودخول المناطق الحساسة", "body": "- المناطق الحساسة في منشأتك (الولادة والأطفال، الصيدلية، المستودعات، غرف الأنظمة) مقيدة الدخول (H-05).\n- تراجع قائمة من يحق له الدخول، وتبلغ عن أي باب مقيد معطل فوراً.", "auto": "procs", "procs": "H-05"}, {"key": "quality", "title": "تقييم الخدمة", "body": "- تقييم كادرك للبلاغات المغلقة يدخل في أداء الأقسام والمقاولين.\n- تشارك في تقييم مقاول النظافة بالتفتيش الدوري (R-32، S-01).\n- ملاحظاتك المتكررة تُرفع لاجتماع الإدارة الشهري عبر المرافق (C-06).", "auto": "procs", "procs": "S-01 · M-04"}, {"key": "reports", "title": "التقارير التي تصلك", "body": "- تقرير الأنظمة الحرجة لمنشأتك: حالة الأنظمة والحالات المفتوحة، ويمكنك إضافة ملاحظة على أي بند.\n- إشعارات الإغلاق والإيقاف والتعطيل الخاصة بمنشأتك.\n- ملخص البلاغات الشهري لمنشأتك من المرافق."}]'::jsonb,'general',4,'hospital') on conflict (code) do nothing;
insert into public.manual_templates(code,title,audience,sections,scope,sort,icon) values ('committee','دليل لجنة الاستلام الفنية','أعضاء لجان الاستلام الابتدائي والنهائي ومهندسو المشاريع','[{"key": "about", "title": "عن هذا الدليل", "body": "لجنة الاستلام هي آخر ضمان قبل أن يدخل المرضى منشأة جديدة أو مؤهلة. هذا الدليل يوحّد طريقة الفحص في كل المشاريع: ماذا يُفحص، وما معيار القبول، ومتى تمنع الملاحظة التشغيل (C-02).", "auto": "procs", "procs": "G-04 · P-13 · P-14"}, {"key": "formation", "title": "تشكيل اللجنة وعملها", "body": "| البند | التفصيل |\n| الرئيس | رئيس قسم المشاريع أو من ينيبه |\n| الأعضاء | المرافق، الصيانة، الأمن والسلامة، وتقنية المعلومات والصيانة الطبية بحسب النطاق، وممثل المنشأة |\n| النصاب | الرئيس والأمن والسلامة والصيانة على الأقل |\n| المقرر | مهندس المشروع |\n| التوقيت | عند إشعار المقاول بالجاهزية، وقبل نهاية الضمان للاستلام النهائي |\n- يفصح العضو عن أي تعارض مصالح مع المقاول قبل الجولة."}, {"key": "stages", "title": "مراحل الاستلام", "body": "| المرحلة | المتطلب | الإجراء |\n| إشعار الجاهزية | المقاول أنهى الأعمال واختبرها ذاتياً | P-13 |\n| الاستلام الابتدائي | فحص اللجنة وتشغيل الأنظمة ومحضر بالملاحظات ومهلها | G-04 |\n| فترة الضمان | بلاغات العيوب ومطالبة المقاول | P-14 |\n| الاستلام النهائي | جولة قبل نهاية الضمان وإغلاق كل الملاحظات | P-14، K-25 |"}, {"key": "docs", "title": "قبل الجولة: الوثائق", "body": "| الوثيقة | تحقق |\n| شهادات اختبار الأنظمة (كهرباء، تكييف، غازات، حريق) | |\n| المخططات كما نُفذ | |\n| كتيبات التشغيل والصيانة | |\n| بيانات الأنظمة ونقاط الإغلاق والخامات (لدليل المنشأة R-42) | |\n| شهادات وخطابات الضمان | |\n| موافقة الدفاع المدني حيث تلزم | |"}, {"key": "arch", "title": "قائمة الفحص: المعماري والتشطيبات", "body": "| البند | معيار القبول |\n| الأرضيات | مستوية، بلا فواصل في المناطق السريرية، بلا تشققات أو انتفاخ |\n| الجدران وحماية الجدران | مستوية ونظيفة، والحماية مثبتة كاملة |\n| الأسقف | مستوية، البلاطات كاملة ونظيفة، الفتحات مغلقة |\n| الأبواب | تفتح وتغلق بسلاسة، الأقفال والمغلقات تعمل، أبواب الحريق تغلق ذاتياً |\n| النوافذ | محكمة، بلا تسرب |\n| دورات المياه | تعمل، بلا تسرب، والمهيأة لذوي الإعاقة مطابقة |\n| اللوحات والإرشاد | مطابقة للهوية ورموز الغرف صحيحة |\n| النظافة | الموقع نظيف وخالٍ من المخلفات |"}, {"key": "elec", "title": "قائمة الفحص: الكهرباء والمولد", "body": "| البند | معيار القبول |\n| اللوحات | جداول الدوائر محدثة، القواطع مميزة، لا حرارة غير طبيعية |\n| مقابس الطوارئ | مميزة وتعمل على التغذية الاحتياطية |\n| الإنارة | كل الوحدات تعمل، وإنارة الطوارئ تعمل عند قطع التغذية |\n| المولد | إقلاع آلي ونقل الحمل عند قطع التغذية العامة باختبار فعلي |\n| التأريض | شهادة اختبار |"}, {"key": "hvac", "title": "قائمة الفحص: التكييف والتهوية", "body": "| البند | معيار القبول |\n| الوحدات | تعمل، بلا أصوات أو تسرب |\n| درجات الحرارة | ضمن التصميم في الفراغات |\n| الضغط في المناطق الخاصة | موجب أو سالب بحسب التصميم بقراءة موثقة |\n| الفلاتر | مركبة ونظيفة |\n| تصريف التكثيف | يعمل بلا تسرب |"}, {"key": "plumb", "title": "قائمة الفحص: الصحي والغازات الطبية", "body": "| البند | معيار القبول |\n| المياه | ضغط مناسب، حار وبارد، بلا تسرب |\n| الصرف | يعمل بلا ارتداد أو روائح |\n| مخارج الغازات | كل مخرج يعطي الغاز الصحيح، باختبار وشهادة |\n| صمامات المنطقة والإنذارات | مميزة، والإنذار يعمل باختبار |"}, {"key": "fire", "title": "قائمة الفحص: السلامة من الحريق", "body": "| البند | معيار القبول |\n| الإنذار | كل الكواشف والكواسر تعمل باختبار، وظهورها على اللوحة |\n| الرشاشات | مركبة كاملة، والصمامات مفتوحة ومراقبة |\n| الطفايات وصناديق الحريق | في مواقعها، مشحونة ومفحوصة |\n| مخارج الطوارئ | خالية، مضاءة، ولوحاتها تعمل |\n| فواصل الحريق | الفتحات مسدودة بمواد معتمدة |\n| مخططات الإخلاء | معلقة في كل طابق |\n! أي ملاحظة حرجة في السلامة من الحريق تمنع التشغيل حتى إغلاقها (R-23).", "auto": "procs", "procs": "H-06"}, {"key": "lv", "title": "قائمة الفحص: التيار الخفيف والأجهزة والمصاعد", "body": "| البند | معيار القبول |\n| الشبكات | شهادات اختبار الكوابل والألياف، واستلام تقنية المعلومات (T-02) |\n| النداء والكاميرات والدخول | تعمل وتغطي المطلوب |\n| مواقع الأجهزة الطبية | التغذيات والغازات والتثبيت جاهزة (G-07) |\n| المصاعد | تعمل، أزرار الطوارئ والاتصال سليمة، وشهادة سلامة سارية |", "auto": "procs", "procs": "T-02 · G-07"}, {"key": "snags", "title": "تصنيف الملاحظات", "body": "| الصنف | التعريف | الإجراء |\n| حرجة | تمس السلامة أو تمنع تقديم الخدمة | تمنع التشغيل حتى الإغلاق |\n| رئيسية | تؤثر على الأداء أو التشغيل دون خطر مباشر | مهلة محددة في المحضر، ويُحتجز ما يقابلها |\n| ثانوية | تشطيبات أو تفاصيل لا تؤثر على التشغيل | مهلة محددة، ولا تؤخر الاستلام |\n- كل ملاحظة بصورة وموقع برمز الغرفة ومسؤول ومهلة."}, {"key": "minutes", "title": "المحضر وملف التسليم", "body": "- محضر الاستلام في المنصة: الحضور، الأنظمة المفحوصة، الملاحظات بأصنافها ومهلها، والتوصية (استلام / استلام بملاحظات / رفض).\n- يُرفع المحضر في المستندات الرسمية للمشروع (P-11)، ويبدأ الضمان من تاريخ الاستلام الابتدائي.\n- لا يكتمل التسليم إلا بدليل التشغيل والصيانة ودليل مستخدمي المنشأة (R-42).\n- يُقيَّم أداء المقاول عند الاستلام ويُسجل في المنصة.", "auto": "procs", "procs": "P-11 · P-13"}, {"key": "final", "title": "الاستلام النهائي", "body": "- قبل انتهاء الضمان بثلاثة أشهر: جولة مشتركة مع الصيانة والمرافق والمنشأة، وقائمة ملاحظات تُسلَّم للمقاول (K-25).\n- يُستلم المشروع نهائياً بعد إغلاق كل الملاحظات وعيوب الضمان، ثم يُفرج عن المبالغ المحتجزة بحسب العقد.", "auto": "procs", "procs": "P-14"}]'::jsonb,'general',5,'clipok') on conflict (code) do nothing;
insert into public.gov_rules(code,title,theme,statement,criteria,owner,process_code,note,sort) values
 ('R-43','دليل المقاول جزء من العقد','التكامل','كل مقاول يعمل داخل منشأة مشغّلة أو بجوارها يلتزم بدليل المقاول، ويُرفق الدليل بكراسة الطرح، ويوقّع المقاول إقرار الالتزام قبل المباشرة.','["يُرفق دليل المقاول بكراسة كل طرح ينفذ داخل منشأة مشغّلة", "لا مباشرة قبل توقيع الإقرار وحفظه في مستندات المشروع", "تُحتسب مخالفات الدليل في تقييم أداء المقاول"]'::jsonb,'PRJ','H-07','',43),
 ('R-44','كل تصميم على دليل المعايير','التكامل','يُرفق دليل معايير التصميم مع كل تكليف تصميم أو تأهيل، ولا يُعتمد تصميم للطرح قبل اجتياز قائمة مراجعته، وأي خروج عنه بمبرر مكتوب يعتمده رئيس قسم المشاريع.','["الدليل مرفق بكل تكليف تصميم", "قائمة مراجعة التصميم مكتملة قبل الاعتماد للطرح (A-03)", "الخروج عن الدليل بمبرر مكتوب ومعتمد"]'::jsonb,'PRJ','P-03','',44)
 on conflict (code) do nothing;
